 <!doctype html>
 <html lang="es">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <meta name="theme-color" content="#090b0a" />
     <meta name="robots" content="noindex" />
     <title>404 | Victor Reguillo</title>
     <link rel="stylesheet" href="assets/functions/orbs/themes/themes.css" />
     <style>
       :root { color-scheme: dark; --ink: #090b0a; --panel: #0d100e; --line: #2b322d; --muted: #858c85; --paper: #e9eee8; --green: #20ef4f; --green-dim: #087d2a; --grid-line: rgba(32, 239, 79, .025); --mono: "DM Mono", "Courier New", monospace; --display: "Space Grotesk", "Trebuchet MS", sans-serif; }
