       html { min-height: 100%; background: var(--ink); }
       body { min-height: 100vh; margin: 0; display: grid; place-items: center; padding: 20px; background-color: var(--ink); background-image: linear-gradient(var(--grid-line) 1px, transparent 1px), linear-gradient(90deg, var(--grid-line) 1px, transparent 1px); background-size: 48px 48px; color: var(--paper); font-family: var(--mono); }
