       .game-box { margin-top: 22px; border: 1px solid var(--line); background: var(--ink); line-height: 0; }
       canvas { display: block; width: 100%; height: auto; touch-action: manipulation; }
       .bar { margin: 0 0 22px; color: var(--green); font-size: 12px; overflow-wrap: anywhere; }
       h1 { margin: 0; color: var(--green); font-family: var(--display); font-size: clamp(64px, 20vw, 110px); line-height: 1; text-shadow: 0 0 18px color-mix(in srgb, var(--green) 35%, transparent); }
