       .cursor { display: inline-block; width: 8px; height: 14px; margin-left: 4px; background: var(--green); vertical-align: -2px; animation: blink 1s steps(1) infinite; }
       @keyframes blink { 50% { opacity: 0; } }
       @media (prefers-reduced-motion: reduce) { .cursor { animation: none; } }
