       <p class="bar">guest@portfolio:~$ cd <span id="path"></span></p>
       <h1>404</h1>
       <p class="err" id="error"></p>
       <p id="hint"></p>
       <p id="game-hint"></p>
       <div class="game-box"><canvas id="dino-canvas" width="900" height="260" aria-label="Dino game"></canvas></div>
       <a href="index.html" id="home"></a><span class="cursor" aria-hidden="true"></span>
