     <script>
       const read = (key) => { try { return localStorage.getItem(key); } catch { return null; } };
       const savedTheme = read("portfolio-theme");
       const theme = savedTheme === "solar" ? "claude" : savedTheme;
       document.body.dataset.theme = ["hacker", "cyberpunk", "claude"].includes(theme) ? theme : "hacker";
       const es = read("portfolio-language") !== "en";
       document.documentElement.lang = es ? "es" : "en";
       document.getElementById("path").textContent = new URLSearchParams(location.search).get("from") || location.pathname;
